// Service worker: precaches every file the app needs, then serves them cache-first.
// The file list and cache name are generated by tools/build-assets.mjs.
importScripts('./asset-list.js');

const CACHE = self.OBSERVATORY_CACHE;
const ASSETS = self.OBSERVATORY_ASSETS;

self.addEventListener('install', (event) => {
  event.waitUntil(
    (async () => {
      const cache = await caches.open(CACHE);
      // cache: 'reload' bypasses the HTTP cache so a new version gets fresh files.
      await cache.addAll(ASSETS.map((url) => new Request(url, { cache: 'reload' })));
      // On the very first install there is no older version to protect, so activate at once.
      if (!self.registration.active) await self.skipWaiting();
    })()
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    (async () => {
      for (const key of await caches.keys()) if (key.startsWith('observatory-') && key !== CACHE) await caches.delete(key);
      await self.clients.claim();
      for (const client of await self.clients.matchAll()) client.postMessage('cached');
    })()
  );
});

self.addEventListener('message', (event) => {
  if (event.data === 'skipWaiting') self.skipWaiting();
});

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  event.respondWith(
    (async () => {
      const cache = await caches.open(CACHE);
      if (req.mode === 'navigate') {
        return (await cache.match('./index.html')) ?? fetch(req);
      }
      const hit = await cache.match(req, { ignoreSearch: true });
      if (hit) return hit;
      try {
        return await fetch(req);
      } catch {
        return new Response('Offline and not cached', { status: 503, statusText: 'Offline' });
      }
    })()
  );
});
